const responseBody = pm.response.json();

if (pm.response.code === 200 && responseBody.token) {
    if (responseBody.user.role === "administrador") {
        pm.collectionVariables.set("adminToken", responseBody.token);
    } else {
        pm.collectionVariables.set("userToken", responseBody.token);
    }
}

if (pm.response.code === 200) {
  const responseBody = pm.response.json();
  if (responseBody.token) pm.collectionVariables.set('token', responseBody.token);
  if (responseBody.user?.user_id) pm.collectionVariables.set('userId', String(responseBody.user.user_id));
}
